styleBlocks.source:
#activity-files,#activity-file-preview{width:min(700px,calc(100vw - 32px));max-height:85vh;overflow:auto;background:var(--ecco-theme-surface,#201d44);color:var(--ecco-theme-text,#eeebf5);border:1px solid var(--ecco-theme-border,#605679);border-radius:9px;padding:18px}
#activity-files{width:min(1100px,calc(100vw - 32px));max-width:calc(100vw - 32px);height:85vh;max-height:900px}#activity-files[open]{display:flex;flex-direction:column}#activity-files>.section-head{margin-bottom:10px}#activity-files-count{margin:8px 0}#activity-files-message:empty{display:none}
#activity-files [hidden]{display:none!important}#activity-files .row,#activity-file-preview .row{display:flex;gap:6px;flex-wrap:wrap}
#activity-files .activity-files-filters{flex-wrap:nowrap;align-items:flex-end;font-size:calc(12px - 2pt)}#activity-files .activity-files-filters>*{flex:1 1 0;min-width:0}#activity-files .activity-files-filters select{min-width:0}
#activity-files .activity-files-table-scroll{flex:1;min-height:0;overflow:auto}#activity-files-table{width:100%;min-width:560px;table-layout:fixed;border-collapse:collapse;font-size:calc(12px - 2pt);text-align:left}#activity-files-table th,#activity-files-table td{border-bottom:1px solid var(--ecco-theme-border,#605679);padding:4px 6px;vertical-align:middle}#activity-files-table th:first-child{width:36%}#activity-files-table th:nth-child(2){width:12%}#activity-files-table th:nth-child(n+3){width:26%}
#activity-files #activity-files-table .activity-file-sort,#activity-files #activity-files-table .activity-file-name{font:inherit;text-align:left;background:transparent;color:inherit;border:0;border-radius:0;padding:0!important;min-height:24px!important;box-shadow:none}#activity-files-table .activity-file-sort{font-weight:650;width:100%}#activity-files-table .activity-file-name{color:var(--ecco-theme-accent,var(--accent,#ffdc24));display:block;width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}#activity-files-table .activity-file-sort span{opacity:.4}#activity-files-table th[aria-sort=ascending] [data-direction=ascending],#activity-files-table th[aria-sort=descending] [data-direction=descending]{opacity:1;color:var(--ecco-theme-accent,var(--accent,#ffdc24))}#activity-files-table tbody tr:hover{background:var(--ecco-theme-control,#302a54)}.activity-file-date{color:var(--ecco-theme-muted,var(--muted,#b1acc9))}
#activity-file-preview .activity-file-media{display:block;width:100%;max-height:50vh;object-fit:contain;margin:16px 0}#activity-file-preview h2,#activity-file-preview .help{overflow-wrap:anywhere}

#openai-key-dialog,:is(#connection-dialog,#disconnect-connections-dialog){width:min(540px,calc(100vw - 32px))}
#openai-key-dialog .row,#openai-connection .row{flex-wrap:wrap;gap:6px}
#openai-key-dialog button,#openai-connection button,:is(#connections,[data-disconnect-items]) [data-storage]{font-size:calc(12px - 2pt);min-height:30px;padding:4px 8px}
.ai-global-control{display:flex;flex-direction:row;align-items:center;gap:8px;margin:14px 0}
.ai-global-control input{width:16px;height:16px;min-height:16px;margin:0;accent-color:var(--accent,#ffdc24)}
#studio-ai-status{display:flex;align-items:center;gap:10px;justify-content:space-between;font-size:calc(12px - 2pt);color:var(--muted);margin:0 0 14px}
#studio-ai-status[data-enabled=true]{color:var(--accent,#ffdc24)}
#studio-ai-status button,.ai-prompt-assist{flex:0 0 auto;width:auto;align-self:flex-start;font-size:calc(12px - 2pt);padding:5px 7px;min-height:28px}
#ai-review-dialog{width:min(760px,calc(100vw - 32px));max-height:85vh;overflow:auto}
#ai-generation-dialog{width:min(620px,calc(100vw - 32px));max-height:85vh;overflow:auto}
#ai-generation-dialog textarea{min-height:150px;line-height:1.5;resize:vertical}
#ai-generation-dialog [hidden]{display:none!important}
#ai-generation-dialog .row{justify-content:flex-end;gap:6px}
#ai-review-dialog details{font-size:calc(12px - 2pt)}#ai-review-dialog textarea{font-size:calc(12px - 2pt);min-height:120px}
#ai-review-dialog .ai-questions{color:var(--accent,#ffdc24);white-space:pre-wrap}
#ai-review-dialog [hidden],#studio-ai-status [hidden],#openai-connection [hidden]{display:none!important}

/* Shared AI editing surfaces retain one instruction/review/Apply layout. */
#ai-generation-dialog,#ai-review-dialog[data-ai-text-refinement],#audio-selection-ai[data-ai-text-refinement]{width:min(660px,calc(100vw - 32px));max-height:85vh;overflow:auto}
#ai-review-dialog[data-ai-text-refinement] textarea,#audio-selection-ai[data-ai-text-refinement] textarea{font-size:calc(14px - 2pt);line-height:1.5;min-height:100px;resize:vertical}
[data-ai-text-refinement] [hidden]{display:none!important}

#studio-ai-status[hidden]{display:none!important}
#studio-ai-button{color:#fff!important;font-size:calc(12px - 2pt);padding:5px 7px;min-height:28px;background:transparent}
#studio-ai-button[data-connected=true]{color:var(--accent,#ffdc24)!important}
body.workspace-entry-mode #studio-ai-button{display:none!important}

#studio-ai-button,#studio-storage-indicator{display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;padding:0;font-size:calc(20px - 2pt);flex:none;color:#fff!important;cursor:default}
#studio-ai-button[data-connected=true],#studio-storage-indicator[data-connected=true]{color:var(--accent,#ffdc24)!important}
body.workspace-entry-mode #studio-storage-indicator{display:none!important}
#connect-storage[hidden],#reconnect-gpu[hidden]{display:none!important}

#connection-indicators{display:inline-flex;align-items:center;gap:6px;padding:4px 8px;border:1px solid rgba(190,180,215,.22);border-radius:10px;background:linear-gradient(180deg,#302a43,#242031);box-shadow:inset 0 1px 3px rgba(0,0,0,.35),0 1px 0 rgba(255,255,255,.04);flex:none}
#connection-indicators>span{width:24px;height:26px;min-height:26px}
body.workspace-entry-mode #connection-indicators{display:none!important}
:is(#connections,[data-disconnect-items]) .connection{padding:14px 0;border-bottom:1px solid rgba(190,180,215,.15)}
:is(#connections,[data-disconnect-items]) .connection:last-child{border-bottom:0}
:is(#connections,[data-disconnect-items]) .connection-heading{display:flex;align-items:center;justify-content:space-between;gap:14px}
:is(#connections,[data-disconnect-items]) .connection-heading h3{margin:0}
:is(#connection-dialog,#disconnect-connections-dialog) button{box-sizing:border-box;width:112px!important;min-height:32px!important;height:32px!important;padding:5px 8px!important;font-size:calc(12px - 2pt)!important;white-space:nowrap}
:is(#connections,[data-disconnect-items]) button[data-connected=true]{color:var(--accent,#ffdc24)!important;border-color:var(--accent,#ffdc24)!important}
:is(#connections,[data-disconnect-items]) .help{margin:8px 0 0;line-height:1.5}
:is(#connections,[data-disconnect-items]) [data-ai-disconnect]{margin-left:auto;display:block}

:is(#connection-dialog,#disconnect-connections-dialog) > .section-head > h2{font-size:calc(18px - 2pt);color:var(--accent,#ffdc24)}

#connection-panel-menu>summary{min-height:26px;padding:0 4px;justify-content:center}
#connection-panel-menu{margin-left:2px}
[data-category="Account"] [data-category="Billing"]>.workspace-menu-items{position:static;box-shadow:none;border:0;min-width:0}

/* Keep AI assistance beside the field label, without adding another panel. */
.ai-prompt-toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;width:100%;min-width:0}
.ai-prompt-label{min-width:0}
.ai-prompt-toolbar>.ai-prompt-assist{align-self:center;margin:0;padding:3px 5px;min-height:24px;line-height:1.3;font-size:calc(11px - 2pt);font-weight:500;white-space:nowrap;border:1px solid transparent;background:transparent;box-shadow:none;color:var(--muted,#b8b0cd)}
.ai-prompt-toolbar>.ai-prompt-assist:hover,.ai-prompt-toolbar>.ai-prompt-assist:focus-visible{color:var(--accent,#ffdc24);border-color:var(--accent,#ffdc24);background:#38305e}
.ai-prompt-toolbar>.ai-prompt-assist:disabled{opacity:.55}
#ai-review-dialog [data-suggestion]{min-height:180px;resize:vertical;line-height:1.5}
#ai-review-dialog .ai-review-notes{white-space:pre-wrap}
#ai-review-dialog [data-apply-status]{color:var(--accent,#ffdc24)}
#ai-review-dialog .row{justify-content:flex-end;gap:6px}
@media(max-width:480px){.ai-prompt-toolbar{gap:4px}.ai-prompt-toolbar>.ai-prompt-assist{font-size:calc(10px - 2pt);padding:3px 5px}}

#story-entry-panel{display:flex;justify-content:flex-end;align-items:center;gap:4px;margin:0 0 16px auto;padding:5px 6px;width:fit-content;max-width:100%;border:1px solid rgba(190,180,215,.22);border-radius:10px;background:linear-gradient(180deg,#302a43,#242031);box-shadow:inset 0 1px 3px rgba(0,0,0,.35);flex-wrap:wrap}
#story-entry-panel>button,#story-entry-panel>details>summary{box-sizing:border-box;font-size:calc(12px - 2pt)!important;min-height:30px!important;height:30px;padding:5px 8px!important;margin:0}
#story-entry-panel [aria-pressed=true],#story-entry-panel details[open]>summary{color:var(--accent,#ffdc24)!important}
#story-entry-panel .workspace-menu-items .row{display:flex;flex-direction:column;align-items:stretch;gap:4px}
#story-pdf-tools[hidden]{display:none!important}

:is(#page,#video-shot-controls,#video-audio-script) .ai-selected-field{border-color:var(--accent,#ffdc24)!important;outline:1px solid var(--accent,#ffdc24);outline-offset:1px}
:is(#storyboard-ai-toolbar,#story-description-ai,#video-flow-ai)>button{flex:0 0 auto;width:auto}

:is(#storyboard-ai-toolbar,#story-description-ai,#video-flow-ai).storyboard-ai-floating{position:fixed;right:24px;bottom:28px;z-index:110}
:is(#storyboard-ai-toolbar,#story-description-ai,#video-flow-ai)>summary{list-style:none;display:grid;place-items:center;width:44px;height:44px;border:1px solid var(--accent,#ffdc24);border-radius:50%;background:#252039;color:var(--accent,#ffdc24);font-weight:700;cursor:pointer;box-shadow:0 4px 16px #0005}
:is(#storyboard-ai-toolbar,#story-description-ai,#video-flow-ai)>summary::-webkit-details-marker{display:none}
:is(#storyboard-ai-toolbar,#story-description-ai,#video-flow-ai) .storyboard-ai-actions{position:absolute;right:0;bottom:54px;min-width:180px;padding:6px;background:#252039;border:1px solid #48405c;border-radius:9px;box-shadow:0 8px 24px #0006}
:is(#storyboard-ai-toolbar,#story-description-ai,#video-flow-ai):not([open]) .storyboard-ai-actions{display:none}
:is(#storyboard-ai-toolbar,#story-description-ai,#video-flow-ai) .storyboard-ai-actions>button{display:block;width:100%;text-align:left;margin:3px 0;white-space:nowrap}
#page:has(:is(#storyboard-ai-toolbar,#story-description-ai,#video-flow-ai)) .ai-prompt-assist{display:none!important}
body:not(.workspace-entry-mode) #save-board.storyboard-save-continue{width:100%;padding:12px 18px!important;min-height:48px!important;font-size:calc(14px - 2pt)!important}

#page .storyboard-save-row{display:block;width:100%}
body:not(.workspace-entry-mode) #page #save-board.storyboard-save-continue{display:block;width:100%!important;max-width:none!important;box-sizing:border-box}


#video-audio-script textarea{min-height:240px;resize:vertical}
#video-audio-script .row{gap:6px;flex-wrap:wrap}

.ai-dialog-close{flex:none!important;margin-left:auto;width:28px!important;height:28px;min-height:28px!important;padding:0!important;font-size:calc(20px - 2pt)!important;line-height:1!important}

#youtube-setup-dialog [hidden],#youtube-connection [hidden]{display:none!important}

/* Share the Image/Video studio grid, panel and form control styles. */
.audio-studio{margin:0;min-width:0}
.audio-studio .audio-workspace{align-items:start}
.audio-model-controls,.audio-line-controls,.audio-output-controls{display:grid;grid-template-columns:minmax(0,1fr);gap:14px}
.audio-studio #audio-form,.audio-studio label{min-width:0}
.audio-studio input,.audio-studio select{min-width:0}
.audio-line{border:1px solid var(--border);border-radius:8px;margin:0 0 16px;padding:10px;min-width:0;display:grid;gap:10px}
.audio-line legend{padding:0 6px;font-size:calc(12px - 2pt);font-weight:600}
.audio-line textarea{width:100%;resize:vertical;min-height:100px}
.audio-line [data-remove-line]{justify-self:start}
.audio-studio #add-audio-line{align-self:flex-start}
.audio-studio #audio-form>.row{flex-direction:column;align-items:stretch}
.audio-card audio{display:block;width:100%;margin:16px 0}
.audio-transcript{white-space:pre-wrap;overflow-wrap:anywhere}
.audio-card .actions{margin-top:14px}
.audio-card h3{overflow-wrap:anywhere}
.audio-studio #audio-job-status:empty{display:none}


.audio-speaker-tabs{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0}
.audio-speaker-tabs [aria-pressed=true],.audio-speaker-tabs [aria-selected=true]{border-color:var(--accent,#ffdc24);color:var(--accent,#ffdc24);box-shadow:0 0 0 1px #ffdc2420}
[data-delivery-controls],[data-speaker-panel]{display:flex;flex-direction:column;gap:10px}
.audio-voice-row,.audio-turn-heading{display:flex;align-items:flex-end;gap:8px}
.audio-voice-row>label,.audio-turn-heading>label{flex:1;min-width:0}
.generation-dialog .audio-voice-preview{display:flex;align-items:center;gap:4px;min-height:32px;flex-shrink:0}
.generation-dialog [data-speaker-field=delivery]{min-height:90px}
.audio-direction-note{margin:0;line-height:1.5}
#audio-voice-preview-dialog{width:min(560px,calc(100vw - 32px))}
#audio-voice-preview-dialog textarea{min-height:100px}
#audio-voice-preview-dialog audio{width:100%}

/* Hide the empty review placeholder once a recording exists. */
.audio-studio [hidden]{display:none!important}
#audio-review-results{min-width:0}
#audio-gallery{min-width:0}
.audio-card-preview{aspect-ratio:16/9;background:#14112b;display:flex;align-items:center;justify-content:center;padding:46px 12px 12px;min-width:0}
.audio-card-preview audio{min-width:0;margin:0}
.audio-card .card-body{min-width:0}

/* Reuse generation controls and popup dimensions for character and script setup. */
[data-audio-characters],.audio-character-names,#audio-script-instructions [data-script-turn-list]{display:flex;flex-direction:column;gap:10px}
#audio-script-instructions .audio-script-brief{display:flex;flex-direction:column;gap:14px;border:0;padding:0;margin:0;min-width:0}
#audio-script-instructions [data-script-review]{border-top:1px solid var(--border);padding-top:14px}
#audio-script-instructions [data-script-status]{white-space:pre-wrap}
#audio-script-instructions .audio-line textarea{min-height:100px}
#audio-script-instructions:modal{position:fixed;inset:0;margin:auto}

/* Guided audio preparation reuses the existing modal, field and theme rules. */
#audio-guided-dialog:modal{position:fixed;inset:0;margin:auto}
#audio-guided-dialog [hidden]{display:none!important}
#audio-guided-dialog [data-stage],#audio-guided-dialog [data-extra-questions],#audio-guided-dialog [data-cast],#audio-guided-dialog [data-turn-list]{display:flex;flex-direction:column;gap:14px;min-width:0}
#audio-guided-dialog .audio-guided-steps{display:flex;flex-wrap:wrap;gap:10px;border-bottom:1px solid var(--border);padding-bottom:10px}
#audio-guided-dialog .audio-guided-steps [aria-current=step]{color:var(--accent);font-weight:600}
#audio-guided-dialog [data-status],#audio-guided-dialog .audio-source-review{white-space:pre-wrap;overflow-wrap:anywhere}
#audio-guided-dialog textarea{min-height:100px}


/* Inline cue review and measured speech progress use the existing theme. */
.audio-inline-cue{border:1px solid var(--border);border-radius:8px;padding:10px;margin:8px 0;min-width:0}
.audio-inline-cue>summary{cursor:pointer}
.audio-inline-cue>.form{margin-top:12px}
.audio-inline-cue audio,[data-speech-progress]{width:100%;accent-color:var(--accent)}
[data-turn-sounds]:empty{display:none}

/* Audio verification and cancellation share the Progress workspace. */
#audio-progress-actions{display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin:16px 0}
#audio-progress-actions button{width:auto;flex:0 1 auto;min-height:32px}
#audio-progress-actions #stop-audio{margin-left:auto}
[data-audio-verification]{margin-top:16px}
[data-verification-summary]{margin:0;font-size:calc(13px - 2pt);line-height:1.5}
[data-verification-checks]{list-style:none;margin:0;padding:0;display:grid;gap:6px}
[data-verification-checks]>li{--check-color:var(--ecco-theme-muted,#b1acc9);border:1px solid var(--ecco-theme-border,#51496f);border-left:3px solid var(--check-color);border-radius:8px;padding:10px;min-width:0;overflow-wrap:anywhere}
[data-verification-checks]>li[data-status=passed]{--check-color:var(--ecco-theme-success,#7bcf9b)}
[data-verification-checks]>li[data-status=failed]{--check-color:var(--ecco-theme-error,#ff6b6b);background:color-mix(in srgb,var(--ecco-theme-error,#ff6b6b) 7%,transparent)}
[data-verification-checks]>li:is([data-status=blocked],[data-status=unverified],[data-status=checking]){--check-color:var(--ecco-theme-accent,#ffdc24)}
.audio-check-heading{display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:4px 10px;font-size:calc(14px - 2pt);line-height:1.5}
.audio-check-state{display:inline-flex;align-items:center;gap:5px;color:var(--check-color);font-size:calc(12px - 2pt);font-weight:600;white-space:nowrap}
[data-check-detail],[data-check-resolution]{margin:6px 0 0;font-size:calc(13px - 2pt);line-height:1.5}
[data-check-detail]{color:var(--ecco-theme-muted,#b1acc9)}
[data-check-resolution]{color:var(--ecco-theme-text,#fff)}
[data-verification-summary][data-status=failed]{color:var(--ecco-theme-error,#ff6b6b)}
[data-verification-summary][data-status=passed]{color:var(--ecco-theme-success,#7bcf9b)}

/* One final-script editor and one shared AI action row. */
.audio-script-heading{align-items:center;flex-wrap:wrap;gap:10px}
.audio-script-heading h3{margin:0}
.audio-script-heading .generation-ai-actions{display:flex;flex-wrap:wrap;gap:6px;margin:0}
#audio-final-script-panel [data-script-edit-status]:empty{display:none}

/* Compact column filters within Flow Verification only. */
.audio-verification-filters{display:flex;flex-wrap:wrap;gap:6px;align-items:end;margin-top:12px}
.audio-verification-filters label{display:grid;gap:4px;flex:1 1 120px;min-width:0;font-size:calc(13px - 2pt)}
.audio-verification-filters input,.audio-verification-filters select{width:100%;min-width:0}
.audio-verification-filters button{width:auto}
[data-verification-checks]>li[hidden]{display:none!important}

[data-audio-task-progress]{display:grid;gap:8px;margin:12px 0}
[data-audio-task-progress][hidden]{display:none!important}
.audio-task-row{border:1px solid var(--ecco-theme-border,#51496f);border-radius:8px;padding:8px}
.audio-task-heading{display:flex;justify-content:space-between;gap:8px;font-size:calc(13px - 2pt)}
.audio-task-row progress{display:block;width:100%;height:6px;accent-color:var(--ecco-theme-accent,#ffdc24);margin:8px 0}
.audio-task-row p{font-size:calc(12px - 2pt);line-height:1.5;margin:0;overflow-wrap:anywhere}
.audio-task-row[data-status=done] [data-task-state]{color:var(--ecco-theme-success,#7bcf9b)}
.audio-task-row:is([data-status=error],[data-status=failed]){border-color:var(--ecco-theme-error,#ff6b6b)}
.audio-task-row:is([data-status=error],[data-status=failed]) [data-task-state]{color:var(--ecco-theme-error,#ff6b6b)}

#audio-workflow-canvas label,#audio-workflow-step label,#audio-workflow-step legend,#audio-workflow-step h2,#audio-workflow-preview h3{color:var(--accent,#ffdc24)}
.audio-workflow-flow{list-style:none;padding:0;margin:20px auto;max-width:680px;display:flex;flex-direction:column;gap:24px}
.audio-workflow-flow li{position:relative}.audio-workflow-flow li:not(:last-child)::after{content:'↓';position:absolute;left:50%;bottom:-24px;color:var(--accent,#ffdc24);font-size:calc(18px - 2pt)}
.audio-workflow-node{width:100%;display:grid;grid-template-columns:32px 1fr;gap:5px 8px;text-align:left;padding:12px!important;border:1px solid #615476!important;border-radius:9px!important}
.audio-workflow-node>span{grid-row:span 2;color:var(--accent,#ffdc24)}.audio-workflow-node>small{grid-column:2;font-weight:400;opacity:.85}.audio-workflow-node:hover,.audio-workflow-node:focus-visible{border-color:var(--accent,#ffdc24)!important;color:var(--accent,#ffdc24)!important}
#audio-workflow-step,#audio-workflow-preview{width:min(640px,92vw);max-height:85vh;overflow:auto}#audio-workflow-step .row{flex-wrap:wrap}#audio-workflow-step .row>label{flex:1;min-width:150px}#audio-workflow-step [hidden]{display:none!important}#audio-workflow-step .audio-workflow-check{display:flex;flex-direction:row;gap:6px}#audio-workflow-step input[type=checkbox]{width:auto}#audio-workflow-step [data-news],#audio-workflow-step [data-book],#audio-workflow-step [data-settings],#audio-workflow-step [data-chapters],#audio-workflow-step fieldset{display:grid;gap:10px}

/* Character workflow reuses existing generation dialog and theme primitives. */
#character-studio-dialog [data-character-body]{display:flex;flex-direction:column;gap:14px}
#character-studio-dialog .character-preview{margin:0;min-width:0}
#character-studio-dialog .character-preview img{width:100%;max-height:50vh;object-fit:contain}
#character-studio-dialog figcaption{color:var(--muted);font-size:calc(12px - 2pt)}
#character-studio-dialog model-viewer{width:100%;height:50vh;background:var(--panel)}
#character-studio-dialog video{width:100%;max-height:50vh}
#character-studio-dialog progress{width:100%;accent-color:var(--accent)}
#character-studio-dialog input[type=radio]{width:auto;min-height:0}
#character-studio-dialog [data-status]{overflow-wrap:anywhere}

/* Scoped additions: existing Studio surfaces and controls keep their dimensions. */
#clip-frame-dialog{--cf-surface:var(--ecco-theme-surface,#242147);--cf-control:var(--ecco-theme-control,#1b1839);--cf-text:var(--ecco-theme-text,#f4f1ff);--cf-border:var(--ecco-theme-border,#51496f);width:min(1400px,96vw);max-width:1400px;max-height:94vh;padding:20px;background:var(--cf-surface);color:var(--cf-text);border:1px solid var(--cf-border);overflow:auto}
#clip-frame-dialog *{box-sizing:border-box}
#clip-frame-dialog [hidden]{display:none!important}
#clip-frame-dialog .cf-head{display:flex;align-items:center;justify-content:space-between;gap:18px;padding-right:76px;margin-bottom:18px}
#clip-frame-dialog h2{font-size:calc(22px - 2pt);letter-spacing:-.4px}
