/* Identical structure, spacing and focus treatment across all generation studios. */
#page .grid:has(>.generation-form),#page .audio-workspace:has(>.generation-form){display:grid;grid-template-columns:minmax(290px,360px) minmax(0,1fr);gap:22px;align-items:start}
#page .generation-form{width:auto;min-width:0;padding:14px;display:flex;flex-direction:column;gap:12px;background:var(--panel,#24203e)}
.generation-section{border:1px solid var(--border,#454065);border-radius:8px;padding:10px;display:flex;flex-direction:column;gap:8px;min-width:0;box-shadow:none}
.generation-section.is-focused{border-color:var(--accent,#ffdc24);box-shadow:0 0 0 1px #ffdc2420}
.generation-section-heading{font-size:calc(13px - 2pt);font-weight:600;color:var(--accent,#ffdc24)}
