.generation-form button,.generation-dialog button{min-height:28px;padding:4px 8px;font-size:calc(12px - 2pt);line-height:1.3;width:auto}
.generation-form input,.generation-form select,.generation-dialog input,.generation-dialog select{width:100%;min-width:0;box-sizing:border-box;min-height:32px;font-size:calc(12px - 2pt)}
.generation-section [data-model]>label{font-size:0;gap:0}
.generation-action{text-align:left}
.generation-settings{padding:0;border:0;background:transparent;box-shadow:none}
.generation-settings>summary{list-style:none;display:flex;justify-content:space-between;align-items:center;padding:4px 0;cursor:pointer;font-size:calc(12px - 2pt);color:var(--muted,#b8b0cd)}
.generation-settings>summary::-webkit-details-marker{display:none}
.generation-settings>summary::after{content:'⌄';font-size:calc(16px - 2pt)}
.generation-settings[open]>summary::after{transform:rotate(180deg)}
.generation-references>summary{font-size:calc(13px - 2pt);font-weight:600;color:var(--accent,#ffdc24)}
.generation-settings-body{display:flex;flex-direction:column;gap:10px;padding-top:10px}
.generation-settings:not([open])>.generation-settings-body{display:none}
.generation-selected,.generation-reference-tabs{display:flex;flex-wrap:wrap;gap:7px}
