.activity>summary{cursor:pointer;font-weight:600;padding:12px 0}.generation-spinner{display:inline-block;width:16px;height:16px;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;animation:generation-spin .8s linear infinite;vertical-align:middle;margin-right:9px}button[aria-busy="true"]{opacity:.85;cursor:wait}@keyframes generation-spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.generation-spinner{animation-duration:2s}}

