.gpu-picker{max-width:1000px;margin:20px auto;padding:28px}.gpu-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin:28px 0}.gpu-card{padding:24px;border:1px solid #4b4766;border-radius:16px;background:#25213f;display:flex;flex-direction:column;gap:12px}.gpu-card h3{font-size:calc(32px - 2pt);margin:0}.gpu-card p{margin:0}.gpu-card .gpu-detail{min-height:58px}.gpu-card .gpu-open{margin-top:auto}.gpu-status{font-weight:600;color:#d3cbeb}.gpu-card[data-status=ready],.gpu-card[data-status=running]{border-color:#36c4aa}.gpu-card[data-status=ready] .gpu-status,.gpu-card[data-status=running] .gpu-status{color:#66e3c9}.gpu-card[data-status=unknown] .gpu-status{color:#e9c97f}@media(max-width:700px){.gpu-grid{grid-template-columns:1fr}.gpu-picker{padding:18px}.gpu-picker .section-head{flex-wrap:wrap;gap:14px}}

/* Match Billing's side-sliding panel; presets affect colors only. */
[data-category="Activity"] .workspace-menu-items{overflow:visible}
#workspace-theme-drawer{display:flex!important;position:absolute;left:100%;top:0;width:100%;min-height:100%;border:1px solid var(--ecco-theme-border,#48405c);border-radius:9px;box-shadow:0 12px 32px #0006;box-sizing:border-box;padding:10px;flex-direction:column;justify-content:center;gap:8px;background:var(--ecco-theme-surface,var(--panel,#252039));z-index:2;visibility:visible;clip-path:inset(0 0 0 0);transition:clip-path .2s ease,visibility .2s}
#workspace-theme-drawer[hidden]{clip-path:inset(0 100% 0 0);visibility:hidden;pointer-events:none}
#workspace-theme-drawer .theme-preset-option{display:flex;flex-direction:row;align-items:center;gap:8px;cursor:pointer;margin:0;color:var(--ecco-theme-text,#fff)}
#workspace-theme-drawer .theme-preset-option:has(input:checked){color:var(--accent,#ffdc24)}
#workspace-theme-drawer input{width:auto;margin:0;accent-color:var(--accent,#ffdc24)}
@media(prefers-reduced-motion:reduce){#workspace-theme-drawer{transition:none}}

/* Shared menu surfaces and independent connection-state colors. */
.workspace-menu>.workspace-menu-items,#workspace-billing-drawer,#workspace-theme-drawer{background-color:var(--ecco-theme-surface,var(--panel,#252039))!important;border-color:var(--ecco-theme-border,#48405c)!important}
#workspace-billing-drawer p{color:var(--ecco-theme-text,#fff)!important}
#connection-indicators{background:linear-gradient(180deg,var(--ecco-theme-control,#302a43),var(--ecco-theme-surface,#242031));border-color:var(--ecco-theme-border,rgba(190,180,215,.22))}
#connection-indicators #studio-ai-button,#connection-indicators #studio-storage-indicator,#connection-indicators #connected-accelerator{color:var(--ecco-theme-disconnected,#fff)!important}
#connection-indicators #studio-ai-button[data-connected=true],#connection-indicators #studio-storage-indicator[data-connected=true],#connection-indicators #connected-accelerator.accelerator-connected{color:var(--ecco-theme-connected,#ffdc24)!important}

