#ecco-activity-tabs{margin:14px 0;gap:6px}#ecco-debug-view{overflow-wrap:anywhere}#ecco-debug-view[hidden],#jobs[hidden]{display:none!important}#ecco-debug-view select,#ecco-debug-view textarea{width:100%;box-sizing:border-box}#ecco-debug-view .debug-image{display:block;max-width:100%;max-height:240px;object-fit:contain;border-radius:8px}#ecco-debug-view figure{margin:10px 0}#ecco-debug-view figcaption{font-size:calc(11px - 2pt);color:#b8b0cd}.debug-facts{display:grid;grid-template-columns:85px 1fr;gap:6px;font-size:calc(12px - 2pt)}.debug-facts dd{margin:0}.debug-facts dt{color:#b8b0cd}#ecco-debug-view pre{white-space:pre-wrap;font-size:calc(11px - 2pt)}#ecco-debug-view h3{font-size:calc(14px - 2pt);margin:18px 0 8px}.debug-error{color:var(--accent,#ffdc24)}

/* Consistent yellow for open menus, selected navigation and icon actions. */
#workspace-menus .workspace-menu[open]>summary,#workspace-menus .workspace-menu>summary:active,#workspace-menus .workspace-menu>summary:focus-visible,#workspace-menus .workspace-menu-items>button:focus,#workspace-menus .workspace-menu-items>a:focus,nav button.active,.workspace-library .tree-folder.selected,.workspace-library[open]>summary,.workspace-library[open]>summary .library-symbol::before,.asset-icon:active,.asset-icon:focus-visible,#workspace-trash{color:var(--accent,#ffdc24)!important}
#workspace-trash svg{stroke:currentColor}

.tree-image{display:flex!important;align-items:center;gap:6px}.tree-image img{width:40px;height:40px;object-fit:cover;border-radius:5px;flex-shrink:0}.tree-image span{overflow:hidden;text-overflow:ellipsis}.card.library-highlight{outline:2px solid var(--accent,#ffdc24);outline-offset:3px}

.library-view-label{display:flex;align-items:center;gap:6px;font-size:calc(12px - 2pt)}.library-view-label select{width:auto;min-width:125px}#library-gallery.library-view-small{display:grid;grid-template-columns:repeat(auto-fill,minmax(165px,1fr));gap:10px}#library-gallery.library-view-large{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:16px}#library-gallery.library-view-list{display:flex;flex-direction:column;gap:6px}#library-gallery.library-view-small .card>img{height:120px;width:100%;object-fit:contain}#library-gallery.library-view-large .card>img{height:280px;width:100%;object-fit:contain}#library-gallery.library-view-list .card{display:grid;grid-template-columns:80px minmax(0,1fr);align-items:center;min-height:85px;padding:6px;position:relative}#library-gallery.library-view-list .card>img{width:72px;height:72px;object-fit:contain}#library-gallery.library-view-list .card-body{padding:4px 68px 4px 10px}#library-gallery.library-view-small .card-body{padding:8px;font-size:calc(12px - 2pt)}#library-gallery.library-view-list .card-body>.help,#library-gallery.library-view-small .card-body>.help{display:none}#library-gallery .library-card-actions>summary{cursor:pointer;color:var(--accent,#ffdc24);font-size:calc(12px - 2pt);margin-top:8px}#library-gallery .library-card-actions:not([open])>.actions{display:none}#library-gallery.library-view-large .library-card-actions>.actions{display:flex}#library-gallery.library-view-large .library-card-actions>summary{display:none}

#ecco-debug-view textarea[aria-label="Submitted prompt"]{font-size:calc(12px - 2pt)!important;line-height:1.45!important;font-family:ui-monospace,SFMono-Regular,Consolas,monospace!important;height:160px;min-height:100px;max-height:280px;overflow:auto;resize:vertical;padding:8px}#ecco-debug-view pre{font-size:calc(11px - 2pt);line-height:1.4;max-height:200px;overflow:auto}

.project>.workspace-library:not([open])>summary,.project>.workspace-library:not([open])>summary>span:not(.library-symbol){color:#fff!important}.project>.workspace-library[open]>summary>span:not(.library-symbol){color:var(--accent,#ffdc24)!important}

#workspace-copyright,#workspace-entry .entry-copyright{color:var(--accent,#ffdc24)!important}

#workspace-trash,#workspace-copyright,#workspace-entry .entry-copyright{color:#fff!important}

/* Activity drawer uses the navigation palette and compact controls. */
#activity-panel{background:#201d44;color:#eeebf5;border-left:1px solid #45405e;padding:18px}
#activity-panel button{width:auto;min-width:0;min-height:28px;padding:4px 8px;font-size:calc(12px - 2pt);line-height:1.4;flex:0 0 auto}
#activity-panel #ecco-activity-tabs{display:flex;justify-content:flex-start;gap:6px;margin:12px 0}
#activity-panel #ecco-activity-tabs button{flex:0 0 auto;width:auto}
#activity-panel #close-activity{width:30px;height:30px;padding:0;font-size:calc(18px - 2pt)}

/* Six-step story creation journey. */
#workspace-production-group.story-journey{margin-top:20px}
.story-journey>h2{font-size:calc(14px - 2pt);font-weight:600;margin:0 0 10px;padding:0 8px;color:var(--text,#eeebf5)}
.story-journey>.workspace-library-content{padding:0;border:0}
