/* Custom story types are edited within the dropdown. */
.story-type-dropdown{position:relative;font-size:calc(12px - 2pt)}
.story-type-dropdown>summary{cursor:pointer;padding:7px 10px;border:1px solid #45405e;border-radius:6px;background:#252039;color:#eeebf5}
.story-type-options{position:absolute;left:0;right:0;top:100%;z-index:30;padding:6px;background:#252039;border:1px solid #605679;border-radius:6px;box-shadow:0 10px 24px #0006}
.story-type-options [data-types]{max-height:220px;overflow:auto;display:flex;flex-direction:column}
.story-type-options [data-types]>button{text-align:left;background:transparent;color:#eeebf5;border:0}
.story-type-options [data-types]>button:hover{background:#38305e;color:var(--accent,#ffdc24)}
.story-type-options [data-custom-entry]{padding-top:6px;border-top:1px solid #45405e}
.story-type-options input{width:100%;box-sizing:border-box;font-size:calc(12px - 2pt)}
.story-type-options .row{margin-top:8px;gap:6px}
.story-type-options [hidden],.story-type-dropdown:not([open])>.story-type-options{display:none!important}

/* Shared field-label color for Tell Your Story. */
#page.story-journey-fields label,
#page.story-journey-fields .ai-prompt-label{color:var(--accent,#ffdc24)!important}
#page.story-journey-fields label input,
#page.story-journey-fields label textarea,
#page.story-journey-fields label select{color:var(--text,#eeebf5)}

#workspace-menus [data-category="Billing"]>summary>span[aria-hidden="true"]{margin-left:auto}

/* Keep the scene count and duration together at the right edge. */
#scene-count-controls{justify-content:flex-end;align-items:flex-end;gap:10px;flex-wrap:nowrap}
#scene-count-controls>label{flex:0 0 auto}



/* Story and Workflow libraries share the other libraries' card and view sizes. */
#story-library-list,#workflow-library-list{gap:10px}
#story-library-list>h3,#workflow-library-list>h3{grid-column:1/-1;margin:12px 0 0}
.text-library-gallery.library-small{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr))}
.text-library-gallery.library-large{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr))}
.text-library-gallery.library-list,#story-library-list.library-list{display:flex;flex-direction:column}
.text-library-card{position:relative;overflow:hidden;min-width:0;border:1px solid #48405c;border-radius:9px;background:#252039}
.text-library-open{display:flex!important;flex-direction:column;align-items:stretch;width:100%;min-width:0;padding:0!important;border:0!important;background:transparent!important;color:inherit!important;text-align:left;box-shadow:none!important}
.text-library-preview{display:flex;align-items:center;justify-content:center;aspect-ratio:16/9;background:#14112b;color:#c6bbdf}
.text-library-preview svg{width:44px;height:44px}
.text-library-caption{display:flex;flex-direction:column;gap:5px;padding:10px 36px 10px 10px;min-width:0}
.text-library-caption strong{font-size:calc(13px - 2pt);line-height:1.4;font-weight:500;overflow-wrap:anywhere}
.text-library-caption small{font-size:calc(11px - 2pt);color:var(--muted,#b1acc9)}
.text-library-caption small:empty{display:none}
.text-library-delete{position:absolute!important;right:5px;top:5px;z-index:1}
.text-library-card:hover,.text-library-card:focus-within{border-color:var(--accent,#ffdc24)}
.library-large .text-library-preview svg{width:64px;height:64px}
.library-list .text-library-open{flex-direction:row;align-items:center}
.library-list .text-library-preview{width:72px;height:72px;aspect-ratio:auto;flex-shrink:0}
.library-list .text-library-preview svg{width:32px;height:32px}
.text-library-row{position:relative;min-width:0}
.text-library-row .text-library-open{flex-direction:row;align-items:center;gap:6px;padding:6px 32px 6px 4px!important;border-radius:5px}
.text-library-row .text-library-preview{width:18px;height:18px;aspect-ratio:auto;flex-shrink:0;background:transparent}
.text-library-row .text-library-preview svg{width:18px;height:18px}
.text-library-row .text-library-caption{padding:0}
.text-library-row .text-library-caption strong{font-size:calc(12px - 2pt);font-weight:400}
.text-library-row .text-library-delete{top:50%;transform:translateY(-50%);right:0}

#story-entry-panel{display:flex;align-items:center;flex-wrap:wrap;gap:10px}
.story-format-source{position:absolute!important;width:1px!important;height:1px!important;overflow:hidden!important;clip-path:inset(50%);white-space:nowrap}
.story-format-control{display:inline-flex;align-items:center;gap:10px;border:1px solid #554a6b;border-radius:9px;padding:5px 8px;background:#252039}
.story-format-control>span{font-size:calc(12px - 2pt);font-weight:500;white-space:nowrap}
.story-format-options{display:flex;gap:4px}
body:not(.workspace-entry-mode) .story-format-options>button{padding:4px 10px!important;min-height:28px!important;font-size:calc(12px - 2pt)!important;border:1px solid transparent!important;border-radius:6px!important;background:transparent!important;color:#d8d3e4!important}
body:not(.workspace-entry-mode) .story-format-options>button.is-selected{border-color:var(--accent,#ffdc24)!important;color:var(--accent,#ffdc24)!important;background:#39304f!important}
.story-format-options>button:focus-visible{outline:2px solid var(--accent,#ffdc24);outline-offset:2px}

/* Match Image Library's small, large and list previews. */
#story-library-list.library-small{grid-template-columns:repeat(auto-fill,minmax(165px,1fr));gap:10px}
#story-library-list.library-large{grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:16px}
#story-library-list.library-small .text-library-preview{height:120px;aspect-ratio:auto}
#story-library-list.library-large .text-library-preview{height:280px;aspect-ratio:auto}
#story-library-list.library-list{gap:6px}
#story-library-list.library-list .card{min-height:85px;padding:6px}
#story-library-list.library-list .text-library-preview{width:72px;height:72px}
#story-library-list .text-library-preview{color:var(--accent,#ffdc24)}
#story-library-list .text-library-open:hover strong,#story-library-list .text-library-open:focus-visible strong{color:var(--accent,#ffdc24)}
.story-source-controls{display:inline-flex;align-items:center;gap:4px;border:1px solid #554a6b;border-radius:9px;padding:5px;background:#252039}
body:not(.workspace-entry-mode) .story-source-controls>button,.story-source-controls>.workspace-menu>summary{padding:4px 8px!important;min-height:28px!important;font-size:calc(12px - 2pt)!important;box-sizing:border-box}
.story-source-controls>.workspace-menu>summary>span{font-size:calc(11px - 2pt)}

/* One marker for every Library navigation item; main-area preview cards stay intact. */
#workspace-library-group .workspace-library>summary>.library-symbol,
#workspace-library-group .text-library-row .text-library-preview{display:none!important}
#workspace-library-group :is(.workspace-library>summary,.tree-folder,.tree-image,.text-library-open,.tree-create,.tree-upload,.video-publish-choice){position:relative;padding-left:24px!important}
#workspace-library-group :is(.workspace-library>summary,.tree-folder,.tree-image,.text-library-open,.tree-create,.tree-upload,.video-publish-choice)::before,
#workspace-library-group .tree-branch-toggle::before{content:'−';position:absolute;left:8px;top:50%;width:12px;height:18px;line-height:16px;font-size:calc(17px - 2pt);border-radius:0;color:var(--accent,#ffdc24);background:transparent;transform:translateY(-50%);pointer-events:none}
#workspace-library-group :is(.workspace-library[open]>summary,summary.active,.tree-folder.selected,.tree-image.selected,.tree-create:focus,.tree-upload:focus,.tree-folder:focus,.tree-image:focus,.video-publish-choice:has(input:checked))::before,
#workspace-library-group .tree-branch-row:has(.tree-folder.selected)>.tree-branch-toggle::before{background:var(--accent,#ffdc24)}
#workspace-library-group .text-library-row .text-library-open.selected{color:var(--accent,#ffdc24)!important}
#workspace-library-group .tree-branch-spacer{display:none}
#workspace-library-group .tree-branch-toggle{position:relative;width:26px!important;min-width:26px!important;flex-basis:26px;font-size:0!important}
#workspace-library-group .tree-branch-row:has(>.tree-branch-toggle)>.tree-folder,
#workspace-library-group .tree-branch-row:has(>.tree-branch-toggle)>.library-selected-row>.tree-folder{padding-left:0!important}
#workspace-library-group .tree-branch-row:has(>.tree-branch-toggle)>.tree-folder::before,
#workspace-library-group .tree-branch-row:has(>.tree-branch-toggle)>.library-selected-row>.tree-folder::before{display:none}
#workspace-library-group .video-publish-choice>input{position:absolute;width:1px!important;height:1px!important;clip-path:inset(50%);overflow:hidden}
#workspace-library-group .video-publish-choice:has(input:checked){color:var(--accent,#ffdc24)}
#workspace-library-group .video-publish-choice:has(input:focus-visible){outline:1px solid var(--accent,#ffdc24);outline-offset:2px}


/* Keep the parent disclosure separate and leave room between item bullets and labels. */
#workspace-library-group>summary::before{display:none}
body:not(.workspace-entry-mode) #workspace-library-group.workspace-library :is(.tree-folder,.tree-image,.text-library-open,.tree-create,.tree-upload,.video-publish-choice){padding-left:24px!important}
body:not(.workspace-entry-mode) #workspace-library-group .tree-branch-row:has(>.tree-branch-toggle)>.tree-folder,
body:not(.workspace-entry-mode) #workspace-library-group .tree-branch-row:has(>.tree-branch-toggle)>.library-selected-row>.tree-folder{padding-left:0!important}

/* Story choices precede workspace navigation. */
body.story-choice-mode{display:block}
body.story-choice-mode>aside{display:none!important}
body.story-choice-mode>main{margin-left:0!important;width:100%;max-width:none}
body.story-choice-mode>main>header{display:flex!important}
body.story-choice-mode #activity-edge-arrow,body.story-choice-mode #activity-panel{display:none!important}
#story-choice-screen{min-height:calc(100dvh - 64px);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:22px}
#story-choice-screen .story-choice-actions{display:flex;flex-direction:column;gap:10px;align-items:stretch;max-width:100%}
#story-choice-screen button{background:#302a54;color:#fff;font-size:calc(12px - 2pt);line-height:1.4;padding:5px 8px;min-height:28px;border-radius:6px;box-shadow:none}
#story-choice-screen button:hover{background:#38305e}
#story-choice-screen button:focus-visible{outline:2px solid white;outline-offset:3px}
#story-choice-screen .entry-logo-particle{animation-play-state:running}

/* Align the two primary sidebar disclosures and their label columns. */
body>aside :is(#workspace-library-group,#workspace-production-group).workspace-library>summary{
 display:flex!important;align-items:center;gap:8px!important;
 padding:8px 5px!important;margin:0!important;font-size:calc(13px - 2pt)!important;
}
body>aside :is(#workspace-library-group,#workspace-production-group).workspace-library>summary::before{display:none!important}
body>aside :is(#workspace-library-group,#workspace-production-group).workspace-library>summary>.library-symbol{
 display:inline-block!important;position:static!important;flex:0 0 12px;width:12px;text-align:center;
}

/* Library categories and label contents use yellow signs instead of bullets. */
body>aside #workspace-library-group .workspace-library>summary>.library-symbol{display:none!important}
body>aside #workspace-library-group .workspace-library>summary::before,
body>aside #workspace-library-group .tree-branch-row::before,
body>aside #workspace-library-group [data-library-marker].tree-folder::before{
 content:'+'!important;display:block!important;position:absolute;left:8px;top:50%;
 transform:translateY(-50%);width:12px;height:18px;line-height:16px;
 font-size:calc(17px - 2pt);font-weight:400;text-align:center;border-radius:0;
 color:var(--accent,#ffdc24)!important;background:transparent!important;pointer-events:none;
}
body>aside #workspace-library-group .tree-branch-row{position:relative;padding-left:24px}
body>aside #workspace-library-group .tree-branch-row::before,
body>aside #workspace-library-group [data-library-marker].tree-folder::before{content:attr(data-library-marker)!important}
body>aside #workspace-library-group .tree-branch-row .tree-folder::before,
body>aside #workspace-library-group .tree-branch-toggle::before{display:none!important}
body>aside #workspace-library-group .tree-branch-row .tree-folder{padding-left:0!important}
body>aside #workspace-library-group .tree-branch-toggle{position:absolute;left:0;top:0;height:100%!important;width:26px!important;min-width:26px!important;padding:0!important;background:transparent!important;z-index:1}

/* No bullets in Library: leaf entries use a yellow minus. */
body>aside #workspace-library-group :is(.tree-folder,.tree-image,.text-library-open,.tree-create,.tree-upload,.video-publish-choice)::before{
 content:'−';width:12px;height:18px;line-height:16px;font-size:calc(17px - 2pt);font-weight:400;
 text-align:center;border-radius:0;color:var(--accent,#ffdc24)!important;background:transparent!important;
}
body>aside #workspace-library-group .tree-create::before{content:'+'}
body>aside #workspace-library-group .tree-branch-row .tree-folder::before{display:none!important}

/* Expanded branches show minus; collapsed branches show plus. */
body>aside #workspace-library-group .workspace-library[open]>summary::before{content:'−'!important}

/* Transparent logo preview: retain the original animation origin and center size. */
:is(#workspace-entry,#story-choice-screen) .entry-logo-motion .entry-logo{width:131.14px;height:131.14px;inset:auto;left:8.55px;top:5.27px;clip-path:circle(15% at 53.67% 52.03%)}
@media(prefers-reduced-motion:reduce){:is(#workspace-entry,#story-choice-screen) .entry-logo-motion .entry-logo{width:156px;height:156px;inset:0;clip-path:none}}

/* Account actions are available from the signed-in user menu. Keep the legacy
   mount hidden for modules that still attach controls there. */
#workspace-menus > .workspace-menu[data-category="Account"]{display:none!important}

/* Community control panel beside Connections; Trash remains in sidebar. */
#workspace-community-controls{display:inline-flex;align-items:center;gap:6px;padding:4px 8px;margin:0;flex:none;border:1px solid var(--ecco-theme-border,rgba(190,180,215,.22));border-radius:10px;background:linear-gradient(180deg,var(--ecco-theme-control,#302a43),var(--ecco-theme-surface,#242031));box-shadow:inset 0 1px 3px rgba(0,0,0,.35),0 1px 0 rgba(255,255,255,.04)}
#workspace-community-controls>#workspace-discord,#workspace-community-controls>#workspace-github{margin:0!important;background:transparent!important;border:0!important;box-shadow:none!important;color:var(--ecco-theme-text,#fff)!important}
#workspace-community-controls>:is(#workspace-discord,#workspace-github):hover,#workspace-community-controls>:is(#workspace-discord,#workspace-github):focus-visible{color:var(--ecco-theme-accent,#ffdc24)!important}
#workspace-community-controls>:is(#workspace-discord,#workspace-github):focus-visible{outline:2px solid var(--ecco-theme-accent,#ffdc24);outline-offset:2px}

#workspace-github{display:inline-flex;align-items:center;justify-content:center;box-sizing:border-box;text-decoration:none;border-radius:6px}
body.workspace-entry-mode #workspace-community-controls{display:none!important}

/* Story generation mirrors the upload workspace size and carries Story Details. */
#ai-generation-dialog.story-generation-dialog{width:min(1600px,96vw);height:min(1000px,94vh);max-width:96vw;max-height:94vh;min-width:min(360px,94vw);min-height:400px;resize:both;overflow:hidden;box-sizing:border-box}
#ai-generation-dialog.story-generation-dialog>form{height:100%;min-height:0}
#ai-generation-dialog.story-generation-dialog .section-head{margin-bottom:0;flex:none}
.story-generation-layout{display:grid;grid-template-columns:minmax(0,2fr) minmax(250px,1fr);gap:14px;flex:1;min-height:0}
.story-generation-prompt{min-height:0;font-size:calc(16px - 2pt);font-weight:600}
.story-generation-prompt textarea{flex:1;width:100%;min-height:130px;resize:none;font-size:calc(16px - 2pt);font-weight:400}
.story-generation-options{border:1px solid #45405e;border-radius:6px;padding:14px;overflow:auto;min-height:0}
.story-generation-options strong{font-size:calc(16px - 2pt)}
#page .story-source-actions>button{flex:0 0 160px;width:160px!important;height:28px!important;min-height:28px!important}
#page .story-source-actions{flex-wrap:wrap;justify-content:flex-end}
@media(max-width:700px){#ai-generation-dialog.story-generation-dialog{overflow:auto}.story-generation-layout{grid-template-columns:minmax(0,1fr);flex:none}.story-generation-prompt textarea{height:35vh}.story-generation-options{overflow:visible}}

.pdf-story-context{margin:0 0 12px;flex:none;overflow-wrap:anywhere}
.source-compatibility-dialog{width:min(640px,94vw)}
.source-compatibility-dialog [data-title]{font-size:calc(20px - 2pt);line-height:1.35}
.source-compatibility-dialog p{margin:0;overflow-wrap:anywhere}
.source-compatibility-context{display:grid;gap:6px;padding:12px;border:1px solid var(--accent,#ffdc24);border-radius:6px;font-size:calc(14px - 2pt)}
.source-compatibility-dialog .row{flex-wrap:wrap}
.source-compatibility-dialog .row>button{flex:1;min-width:160px}

#toggle-activity{display:none!important}
#activity-panel{display:block!important;position:fixed;top:0;right:0;bottom:0;width:min(480px,calc(100vw - 48px));box-sizing:border-box;z-index:90;transform:translateX(0);visibility:visible;transition:transform .25s ease,visibility .25s;overflow-y:auto}
#activity-panel[hidden]{display:block!important;transform:translateX(100%);visibility:hidden;pointer-events:none}
#activity-edge-arrow{position:fixed;right:0;top:50%;transform:translateY(-50%);z-index:91;width:40px;height:64px;padding:0;border-radius:10px 0 0 10px;font-size:calc(25px - 2pt);background:#38305e;color:#eeebf5;border:1px solid #70658c;transition:right .25s ease}
#activity-edge-arrow.drawer-open{right:min(480px,calc(100vw - 48px))}
body.workspace-entry-mode #activity-edge-arrow,body.workspace-entry-mode #activity-panel{display:none!important}
@media(prefers-reduced-motion:reduce){#activity-panel,#activity-edge-arrow{transition:none}}

body > #activity-edge-arrow{position:fixed;right:0;top:50%;width:34px;height:48px;min-width:34px;padding:0;border-radius:8px 0 0 8px;font-size:calc(21px - 2pt);color:var(--accent,#ffdc24);transform:translate(110%,-50%);opacity:0;pointer-events:none;transition:transform .2s ease,opacity .2s ease,right .25s ease}
body > #activity-edge-arrow.edge-near,body > #activity-edge-arrow.drawer-open,body > #activity-edge-arrow:focus-visible{transform:translate(0,-50%);opacity:1;pointer-events:auto}
body > #activity-edge-arrow.drawer-open{right:min(480px,calc(100vw - 48px))}
body > #activity-edge-arrow.has-active-jobs{width:56px}
@media(hover:none),(pointer:coarse){body > #activity-edge-arrow{transform:translate(0,-50%);opacity:.65;pointer-events:auto}body > #activity-edge-arrow.drawer-open{opacity:1}}
@media(prefers-reduced-motion:reduce){body > #activity-edge-arrow{transition:none}}

#connected-accelerator{display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;padding:0;background:transparent!important;color:#fff!important;border:0;box-shadow:none;cursor:default;flex:none}
#connected-accelerator.accelerator-connected{color:var(--accent,#ffdc24)!important}
#connected-accelerator:focus-visible{outline:2px solid #eeebf5;outline-offset:3px}
